5	const SCHEMA = `
6	CREATE TABLE IF NOT EXISTS shadows (
7	  device_id TEXT PRIMARY KEY,
8	  document TEXT NOT NULL,
9	  version INTEGER NOT NULL
10	);
11	CREATE TABLE IF NOT EXISTS rules (
12	  id TEXT PRIMARY KEY,
13	  document TEXT NOT NULL
14	);
15	CREATE TABLE IF NOT EXISTS rule_state (
16	  rule_id TEXT NOT NULL,
17	  device_id TEXT NOT NULL,
18	  matched INTEGER NOT NULL,
19	  PRIMARY KEY (rule_id, device_id)
20	);
21	CREATE TABLE IF NOT EXISTS events (
22	  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
23	  rule_id TEXT NOT NULL,
24	  event TEXT NOT NULL,
25	  source TEXT NOT NULL,
26	  device_id TEXT,
27	  topic TEXT,
28	  value TEXT NOT NULL,
29	  occurred_at TEXT NOT NULL
30	);
31	CREATE TABLE IF NOT EXISTS retained (
32	  topic TEXT PRIMARY KEY,
33	  payload TEXT NOT NULL,
34	  qos INTEGER NOT NULL
35	);
36	CREATE TABLE IF NOT EXISTS idempotency (
37	  key TEXT PRIMARY KEY,
38	  operation TEXT NOT NULL,
39	  response TEXT NOT NULL
40	);
41	CREATE TABLE IF NOT EXISTS telemetry_samples (
42	  device_id TEXT NOT NULL,
43	  metric TEXT NOT NULL,
44	  ts INTEGER NOT NULL,
45	  value REAL NOT NULL,
46	  seq INTEGER PRIMARY KEY AUTOINCREMENT
47	);
48	CREATE INDEX IF NOT EXISTS telemetry_query
49	  ON telemetry_samples (device_id, metric, ts);
50	`;
51	
52	export class Store {
53	  constructor(path) {
54	    if (path !== ":memory:") {
55	      mkdirSync(dirname(path), { recursive: true });
56	    }
57	    this.database = new DatabaseSync(path);
58	    this.database.exec("PRAGMA journal_mode = WAL");
59	    this.database.exec(SCHEMA);
60	  }
61	
62	  close() {
63	    this.database.close();
64	  }
65	
66	  transaction(action) {
67	    this.database.exec("BEGIN IMMEDIATE");
68	    try {
69	      const result = action();
70	      this.database.exec("COMMIT");
71	      return result;
72	    } catch (error) {
73	      this.database.exec("ROLLBACK");
74	      throw error;
75	    }
76	  }
77	
78	  /**
79	   * Documents are stored as JSON with their insertion order preserved, so a
80	   * document read back from the store is byte-identical to the document that
81	   * was written and an idempotent replay returns the original bytes.
82	   */
83	  encode(value) {
84	    return JSON.stringify(value);
85	  }
86	
87	  decode(value) {
88	    return JSON.parse(value);
89	  }
90	
91	  getShadow(deviceId) {
92	    const row = this.database.prepare("SELECT document FROM shadows WHERE device_id = ?").get(deviceId);
93	    return row ? this.decode(row.document) : null;
94	  }
95	
96	  putShadow(deviceId, document) {
97	    this.database
98	      .prepare(
99	        `INSERT INTO shadows (device_id, document, version) VALUES (?, ?, ?)
100	         ON CONFLICT(device_id) DO UPDATE SET document = excluded.document, version = excluded.version`,
101	      )
102	      .run(deviceId, this.encode(document), document.version);
103	  }
104	
105	  getRule(id) {
106	    const row = this.database.prepare("SELECT document FROM rules WHERE id = ?").get(id);
107	    return row ? this.decode(row.document) : null;
108	  }
109	
110	  insertRule(rule) {
111	    this.database.prepare("INSERT INTO rules (id, document) VALUES (?, ?)").run(rule.id, this.encode(rule));
112	  }
113	
114	  listRules() {
